window.VF2_UNITS = {"7":{"unit":7,"code":"VF2-U07","title":"HEALTH & FITNESS","startNumber":114,"endNumber":134,"entries":[{"number":114,"term":"prescribe (v) · prescription (n)","spoken":"prescribe , prescription","ipa":"prescribe /prəˈskraɪb/ · prescription /prəˈskrɪpʃən/","type":"verb · noun · word family","meaning":"kê đơn · đơn thuốc","definition":"To officially advise and authorize a particular medicine or treatment; prescription is the written instruction.","note":"","example":"The doctor prescribed antibiotics and explained every instruction on the prescription."},{"number":115,"term":"infect (v) · infectious (a) · infection (n) # inject (v) · injection (n)","spoken":"infect , infectious , infection , inject , injection","ipa":"infect /ˌɪˈnfɛkt/ · infectious /ˌɪˈnfɛkʃəs/ · infection /ˌɪˈnfɛkʃən/ · inject /ˌɪˈndʒɛkt/ · injection /ˌɪˈndʒɛkʃən/","type":"verb · noun · adjective · word family","meaning":"làm nhiễm bệnh · có khả năng lây nhiễm · sự nhiễm bệnh hoặc nhiễm trùng · tiêm hoặc truyền vào · mũi tiêm, sự tiêm","definition":"Infect relates to disease transmission; inject means to put a substance into the body with a needle.","note":"infect/infection liên quan nhiễm bệnh; inject/injection liên quan tiêm. Hai nhóm gần giống chữ nhưng khác nghĩa hoàn toàn.","example":"The virus can infect patients and cause an infection, whereas a nurse injects medicine by giving an injection."},{"number":116,"term":"plaster (n) ~ cast (n) # bandage (n)","spoken":"plaster , cast , bandage","ipa":"plaster /ˈplæstɚ/ · cast /kæst/ · bandage /ˈbændɪdʒ/","type":"noun · word family","meaning":"lớp bột hoặc dụng cụ cố định xương gãy · băng quấn vết thương hoặc chỗ bị thương","definition":"A plaster or cast holds a broken bone in place; a bandage covers or supports an injured area.","note":"plaster/cast cố định xương gãy; bandage quấn và bảo vệ vết thương.","example":"The doctor put her broken arm in a cast and wrapped the cut in a clean bandage."},{"number":117,"term":"ward (n)","spoken":"ward","ipa":"ward /wɔːrd/","type":"noun","meaning":"phòng bệnh (trong bệnh viện)","definition":"A room or section of a hospital where patients receive care.","note":"","example":"Visitors must report to the nurses' station before entering the children's ward."},{"number":118,"term":"dose (n)","spoken":"dose","ipa":"dose /doʊs/","type":"noun","meaning":"liều thuốc","definition":"A measured amount of medicine taken at one time.","note":"","example":"Patients should never take more than the recommended dose of this medicine."},{"number":119,"term":"appoint (v) · appointment (n)","spoken":"appoint , appointment","ipa":"appoint /əˈpɔɪnt/ · appointment /əˈpɔɪntmənt/","type":"verb · noun · word family","meaning":"bổ nhiệm · cuộc hẹn; sự bổ nhiệm","definition":"To officially choose somebody for a role; an appointment can also be an arranged meeting.","note":"appoint là bổ nhiệm; appointment là cuộc hẹn hoặc sự bổ nhiệm, tùy ngữ cảnh.","example":"The hospital appointed a new surgeon, and my appointment with her is on Friday."},{"number":120,"term":"spread (v,n)","spoken":"spread","ipa":"spread /sprɛd/","type":"verb · noun","meaning":"lan rộng/làm lan rộng · sự lan rộng hoặc phạm vi lan rộng","definition":"To extend something over a larger area or pass from one person or place to another; as a noun, spread is the process or extent of this movement.","note":"","example":"The rapid spread of the infection was controlled before it could spread to other buildings."},{"number":121,"term":"attempt (v,n) ~ effort (n) · make an attempt ~ make an effort","spoken":"attempt , effort , make an attempt , make an effort","ipa":"attempt /əˈtɛmpt/ · effort /ˈɛfɚt/ · make /meɪk/","type":"verb · noun · word family","meaning":"thử hoặc cố làm; một lần thử ~ sự nỗ lực, công sức · thực hiện một lần thử ~ nỗ lực cố gắng","definition":"An act of trying to do something difficult; effort is the energy used.","note":"attempt là một lần thử; effort là công sức. make an attempt/effort đều đúng nhưng sắc thái khác nhau.","example":"Researchers made several attempts to develop the vaccine and invested considerable effort in each trial."},{"number":122,"term":"worth (pre) + V-ing","spoken":"worth + doing","ipa":"worth /wɝːθ/","type":"preposition · phrase / pattern","meaning":"đáng…","definition":"Used before an -ing form to say that something deserves the time or effort.","note":"worth là giới từ/tính từ đặc biệt, đi với noun hoặc V-ing: worth reading, không dùng worth to read.","example":"The treatment is worth considering because its benefits are supported by reliable evidence."},{"number":123,"term":"emphasize (v) · emphasis (n)","spoken":"emphasize , emphasis","ipa":"emphasize /ˈɛmfəˌsaɪz/ · emphasis /ˈɛmfəsəs/","type":"verb · noun · word family","meaning":"nhấn mạnh · sự nhấn mạnh","definition":"To give special importance to something; emphasis is the related noun.","note":"","example":"The report emphasizes prevention, placing particular emphasis on regular screening."},{"number":124,"term":"addict (n) · addiction (n) · addictive (a) · addicted (a)","spoken":"addict , addiction , addictive , addicted","ipa":"addict /əˈdɪkt/ · addiction /əˈdɪkʃən/ · addictive /əˈdɪktɪv/ · addicted /əˈdɪktɪd/","type":"noun · adjective · word family","meaning":"người nghiện · sự nghiện, chứng nghiện · gây nghiện · bị nghiện","definition":"An addict has an addiction; addictive describes something that can cause dependence, while addicted describes the affected person.","note":"addict là người nghiện; addictive mô tả thứ gây nghiện; addicted mô tả người bị nghiện.","example":"Nicotine is addictive, and an addicted smoker may need support to overcome the addiction."},{"number":125,"term":"surgery (n) · surgeon (n) · surgical (a)","spoken":"surgery , surgeon , surgical","ipa":"surgery /ˈsɝːdʒɚi/ · surgeon /ˈsɝːdʒən/ · surgical /ˈsɝːdʒɪkəl/","type":"noun · adjective · word family","meaning":"phẫu thuật · bác sĩ phẫu thuật · thuộc phẫu thuật","definition":"Medical treatment involving an operation; a surgeon performs it, and surgical is the adjective.","note":"surgery thường không đếm được khi nói chung/hành động phẫu thuật; surgeon là bác sĩ, surgical là tính từ.","example":"The surgeon performed the surgery using a less invasive surgical technique."},{"number":126,"term":"break out","spoken":"break out","ipa":"break /breɪk/ · out /aʊt/","type":"phrasal verb","meaning":"bùng nổ (dịch bệnh, hỏa hoạn, thiên tai…)","definition":"To start suddenly and spread, especially a disease, fire, war, or disaster.","note":"","example":"A new strain of flu broke out shortly after the winter holiday."},{"number":127,"term":"bring on ~ cause","spoken":"bring on , cause","ipa":"bring /brɪŋ/ · cause /kɑːz/","type":"phrasal verb · word family","meaning":"gây ra, dẫn đến","definition":"To cause an illness or unpleasant condition to develop.","note":"","example":"Lack of sleep can bring on headaches and reduce concentration."},{"number":128,"term":"come down with","spoken":"come down with","ipa":"come /kʌm/ · down /daʊn/","type":"phrasal verb","meaning":"mắc bệnh (bệnh vặt)","definition":"To become ill with a usually minor disease.","note":"","example":"I came down with a mild cold but recovered after two days of rest."},{"number":129,"term":"come round / to","spoken":"come round or to","ipa":"come /kʌm/ · round /raʊnd/","type":"phrasal verb","meaning":"tỉnh lại (sau khi ngất/gây mê…)","definition":"To become conscious again after fainting or anaesthesia.","note":"","example":"The patient came round slowly after the operation and recognized the nurse."},{"number":130,"term":"feel up to doing st","spoken":"feel up to doing something","ipa":"feel /fiːl/ · up /ʌp/","type":"phrase / pattern","meaning":"cảm thấy đủ khỏe để…","definition":"To feel healthy, energetic, or willing enough to do something.","note":"Giữ đúng mẫu từ đi kèm: feel up to doing st.","example":"She did not feel up to attending class while she was recovering from the infection."},{"number":131,"term":"get over ~ overcome","spoken":"get over , overcome","ipa":"get /ɡɛt/ · over /ˈoʊvɚ/ · overcome /ˈoʊvɚˌkʌm/","type":"phrasal verb · word family","meaning":"vượt qua, khắc phục","definition":"To recover from an illness or successfully deal with a difficulty.","note":"get over thường là hồi phục sau bệnh/cú sốc; overcome nhấn mạnh vượt qua khó khăn bằng nỗ lực.","example":"Most patients get over the illness quickly, but some struggle to overcome the resulting fatigue."},{"number":132,"term":"pass out ~ faint # pass away ~ die","spoken":"pass out , faint , pass away , die","ipa":"pass /pæs/ · out /aʊt/ · faint /feɪnt/ · away /əˈweɪ/ · die /daɪ/","type":"phrasal verb · word family","meaning":"ngất, bất tỉnh · qua đời, chết","definition":"To become unconscious versus the polite expression for dying.","note":"pass out = ngất; pass away = qua đời. Hai cụm không liên quan nghĩa dù cùng bắt đầu bằng pass.","example":"He passed out because of the heat; his grandfather had passed away several years earlier."},{"number":133,"term":"wear off # wear out","spoken":"wear off , wear out","ipa":"wear /wɛr/ · off /ɔːf/ · out /aʊt/","type":"phrasal verb · word family","meaning":"dần mất tác dụng hoặc cảm giác · mòn hỏng do sử dụng; làm ai kiệt sức","definition":"Wear off means gradually lose an effect or feeling; wear out means become unusable through use or make somebody exhausted.","note":"wear off là tác dụng/cảm giác giảm dần; wear out là vật bị mòn hỏng hoặc người kiệt sức.","example":"The medicine wore off before the old support bandage wore out."},{"number":134,"term":"pull through ~ survive","spoken":"pull through , survive","ipa":"pull /pʊl/ · through /θruː/ · survive /sɚˈvaɪv/","type":"phrasal verb · word family","meaning":"qua khỏi, sống sót sau bệnh hoặc tình trạng nguy hiểm","definition":"To survive and recover from a serious illness or dangerous situation.","note":"","example":"Despite serious injuries, the patient pulled through and later returned to work."}],"pronunciationFocus":[{"entryNumber":115,"points":[{"category":"common-error","note":"infect có /f/; inject có /dʒ/ ở giữa từ"},{"category":"word-stress","note":"infect /ˌɪˈnfɛkt/ và inject /ˌɪˈndʒɛkt/ đều nhấn âm tiết thứ hai"}]},{"entryNumber":123,"points":[{"category":"final-sound","note":"emphasize kết thúc bằng /z/; emphasis kết thúc bằng /s/"}]},{"entryNumber":125,"points":[{"category":"word-stress","note":"surgery, surgeon và surgical đều có trọng âm chính ở âm tiết đầu"}]},{"entryNumber":126,"points":[{"category":"linking","note":"break‿out: nối /k/ sang /aʊ/"}]}]}};
